// T12 renderer: golden frames generated by tools/arduino/oracle/t12_render_oracle.py
// (the real ui.py under CPython), plus geometry invariants from ui.py and the
// Orion.py splash/sleep timing. Expected values never come from this renderer.
#include <cstdint>
#include <cstdio>

#include "app/renderer.hpp"

static int g_failures = 0;
#define CHECK(x) do { if (!(x)) { std::fprintf(stderr, "%s:%d: CHECK(%s) failed\n", __FILE__, __LINE__, #x); ++g_failures; } } while (false)

using namespace orbit;
using namespace orbit::render;

struct GoldenCase {
  const char* name;
  std::uint32_t checksum;  // FNV-1a 32 over the 1024-byte SH1106 page buffer
  UiModel (*make)();
};

namespace {
#include "fixtures/t12_render_traces.inc"

std::uint32_t fnv1a32(const std::uint8_t* data, std::size_t length) {
  std::uint32_t value = 0x811C9DC5U;
  for (std::size_t i = 0; i < length; ++i) {
    value ^= data[i];
    value *= 0x01000193U;
  }
  return value;
}

Assets g_assets;

void assets_and_font_mapping() {
  CHECK(g_assets.load());
  CHECK(g_assets.font.tiles() >= 69);  // every FONTCHARS entry has a glyph
  CHECK(g_assets.chain_nav.tiles() >= 5);
  CHECK(g_assets.chain_preview.tiles() >= 4);
  CHECK(g_assets.state_icons.tiles() >= 5);
  // Positions in ui.py FONTCHARS (space first, two apostrophes, one backslash).
  CHECK(font_tile_for(' ') == 0);
  CHECK(font_tile_for('A') == 1);
  CHECK(font_tile_for('Z') == 26);
  CHECK(font_tile_for('0') == 27);
  CHECK(font_tile_for('?') == 40);
  CHECK(font_tile_for('\'') == 43);
  CHECK(font_tile_for('\\') == 58);
  CHECK(font_tile_for('`') == 68);
  CHECK(font_tile_for('a') == 0);  // lowercase is not in the table
}

void golden_frames() {
  for (const GoldenCase& golden : t12_fixture::kCases) {
    const UiModel model = golden.make();
    Frame frame;
    render_screen(model, g_assets, frame);
    const std::uint32_t got = fnv1a32(frame.bytes, kFrameBytes);
    if (got != golden.checksum) {
      std::fprintf(stderr, "golden %s: got 0x%08X expected 0x%08X\n", golden.name,
                   static_cast<unsigned>(got), static_cast<unsigned>(golden.checksum));
    }
    CHECK(got == golden.checksum);
  }
}

// Frame invariants that hold for every screen: header and footer bars are
// white, and the screen body below the header is untouched by the bars.
void bars_and_gaps() {
  for (const GoldenCase& golden : t12_fixture::kCases) {
    const UiModel model = golden.make();
    Frame frame;
    render_screen(model, g_assets, frame);
    CHECK(frame.pixel(127, 0));
    CHECK(frame.pixel(127, 10));
    CHECK(frame.pixel(127, 53));
    CHECK(frame.pixel(127, 63));
    CHECK(!frame.pixel(127, 11));  // gap between header bar and body
    CHECK(!frame.pixel(127, 52));
  }
}

// Parameter selection draws a white 2x10 cursor at x 0..1 on the highlighted
// row; edit mode moves the same cursor to the right edge.
void parameter_cursor() {
  UiModel model{};
  model.section = UiSection::ParmSelection;
  model.active_chain = 2;
  model.active_parm = 0;
  model.highlight_row = 0;
  model.parm_count = 2;
  model.rows[0].label = "RATE";
  model.rows[0].present = true;
  Frame frame;
  render_screen(model, g_assets, frame);
  CHECK(frame.pixel(0, 15) && frame.pixel(1, 24));
  CHECK(!frame.pixel(0, 25));
  CHECK(!frame.pixel(126, 15));

  model.section = UiSection::ParmEdit;
  render_screen(model, g_assets, frame);
  CHECK(frame.pixel(126, 15) && frame.pixel(127, 24));
  CHECK(!frame.pixel(0, 15));
}

// Chain and module markers are 2x5 black rectangles over the white header
// (drawn after the header, so they cut through the bar).
void markers_over_header() {
  UiModel model{};
  model.section = UiSection::ParmSelection;
  model.active_chain = 2;
  model.active_parm = -2;
  model.highlight_row = -2;
  model.parm_count = 2;
  model.rows[0].label = "RATE";
  model.rows[0].present = true;
  Frame frame;
  render_screen(model, g_assets, frame);
  CHECK(!frame.pixel(0, 3) && !frame.pixel(1, 7));
  CHECK(frame.pixel(0, 8));  // marker is five pixels tall: y 3..7
  CHECK(frame.pixel(2, 3));

  model.active_parm = -1;
  model.highlight_row = -1;
  model.slots[2].label = "TRNS";  // label length 4: x = 64 - (6 - 4) * 6 = 52
  render_screen(model, g_assets, frame);
  CHECK(!frame.pixel(52, 3) && !frame.pixel(53, 7));
  CHECK(frame.pixel(51, 3));
  CHECK(frame.pixel(54, 3));
}

// A module without parameters leaves the rows blank and draws no cursor
// (ParameterSection.rebuild_parm_section returns before cursor_change_state).
void empty_module_has_no_cursor() {
  UiModel model{};
  model.section = UiSection::ParmSelection;
  model.active_chain = 2;
  model.active_parm = -2;
  model.parm_count = 0;
  Frame frame;
  render_screen(model, g_assets, frame);
  CHECK(frame.pixel(0, 3) && frame.pixel(0, 7));
}

// The layout row comes from the parm fields, not the device-supplied
// highlight_row: negative selections enlarge row 0 (as in the Python layout).
void layout_ignores_device_highlight() {
  UiModel model{};
  model.section = UiSection::ParmSelection;
  model.active_chain = 2;
  model.active_parm = -1;
  model.parm_count = 2;
  model.rows[0].label = "RATE";
  model.rows[0].present = true;
  Frame with_device_row;
  model.highlight_row = -1;
  render_screen(model, g_assets, with_device_row);
  Frame other_device_row;
  model.highlight_row = 3;
  render_screen(model, g_assets, other_device_row);
  for (int y = 0; y < kHeight; ++y) {
    for (int x = 0; x < kWidth; ++x) {
      CHECK(with_device_row.pixel(x, y) == other_device_row.pixel(x, y));
    }
  }
}

void power_timing() {
  ScreenPower power;
  power.start(0);
  CHECK(power.phase() == ScreenPhase::Splash);
  CHECK(!power.tick(1499));
  CHECK(power.phase() == ScreenPhase::Splash);
  CHECK(!power.tick(1500));
  CHECK(power.phase() == ScreenPhase::Active);

  // Strictly more than 60000 ms of inactivity puts the display to sleep.
  CHECK(!power.tick(60000));
  CHECK(power.tick(60001));
  CHECK(power.phase() == ScreenPhase::Asleep);
  CHECK(!power.tick(70000));  // already asleep: no second transition

  // Any activity wakes once and restarts the idle window.
  CHECK(power.activity(70000));
  CHECK(power.phase() == ScreenPhase::Active);
  CHECK(!power.activity(70001));
  CHECK(!power.tick(130000));
  CHECK(power.tick(130002));
}

void power_timing_wraps() {
  ScreenPower power;
  const std::uint32_t start = 0xFFFFF000U;
  power.start(start);
  CHECK(!power.tick(start + 1499U));
  CHECK(!power.tick(start + 1500U));  // wrap-safe splash deadline
  CHECK(power.phase() == ScreenPhase::Active);
  CHECK(!power.tick(start + 60000U));
  CHECK(power.tick(start + 60001U));
}

}  // namespace

int main() {
  assets_and_font_mapping();
  golden_frames();
  bars_and_gaps();
  parameter_cursor();
  markers_over_header();
  empty_module_has_no_cursor();
  layout_ignores_device_highlight();
  power_timing();
  power_timing_wraps();
  if (g_failures != 0) {
    std::fprintf(stderr, "t12_renderer: %d failure(s)\n", g_failures);
    return 1;
  }
  std::printf("t12_renderer: %zu golden frames and invariants passed\n",
              sizeof(t12_fixture::kCases) / sizeof(t12_fixture::kCases[0]));
  return 0;
}
